import {Brain,Arena,rng,clamp} from './core.mjs';
const $=id=>document.getElementById(id);let arena=new Arena(42),brain,shuffled,mode='brain',running=false,ready=false,speed=1,difficulty=1,blind=false,action=0,steps=0,random=rng(42),last=0,accumulator=0,trace=[],logs=[],comparison=null;const keys=new Set();
const time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
$('arena').tabIndex=0;
const names={brain:'视觉回路',shuffle:'打乱连接',random:'随机控制',human:'手动控制'};
const descriptions={brain:'公开连线固定不变，仅校准游戏输出接口。',shuffle:'重新排列连接目标，同样校准输出接口。',random:'每 4 个模拟步采样一次随机动作。',human:'用 ↑ ↓ / W S，或在球场内拖动球拍。'};
function log(message){logs.unshift({time:time(arena.elapsed),message});logs=logs.slice(0,80);$('log').replaceChildren(...logs.slice(0,15).map(l=>{const row=document.createElement('div'),t=document.createElement('time'),s=document.createElement('span');t.textContent=l.time;s.textContent=l.message;row.append(t,s);return row;}));}
function pause(value){if(!ready)return;running=value;$('toggle').textContent=running?'Ⅱ 暂停实验':'▶ 继续实验';$('status').textContent=running?'实验进行中':'已暂停';$('pause-overlay').hidden=running;}
function reset(){arena=new Arena(42);random=rng(42);brain?.reset();shuffled?.reset();steps=0;action=0;trace=[];accumulator=0;log(`新一轮 · ${names[mode]} · 种子 0042`);stats();}
$('toggle').onclick=()=>pause(!running);$('reset').onclick=reset;
$('mode').onchange=e=>{mode=e.target.value;$('mode-description').textContent=descriptions[mode];$('player-name').textContent=names[mode];$('blind').disabled=mode==='human'||mode==='random';reset();if(mode==='human')$('arena').focus();};
$('speeds').onclick=e=>{const button=e.target.closest('[data-speed]');if(!button)return;speed=+button.dataset.speed;for(const b of $('speeds').children)b.classList.toggle('selected',b===button);};
$('difficulty').oninput=e=>{difficulty=+e.target.value;$('difficulty-value').textContent=difficulty<.9?'舒缓':difficulty>1.2?'挑战':'标准';};
$('difficulty').onchange=()=>log(`球速调整至 ${difficulty.toFixed(2)}×`);
$('blind').onchange=e=>{blind=e.target.checked;brain.reset();shuffled.reset();log(blind?'已切断感觉输入':'已恢复感觉输入');};
$('about').onclick=()=>{$('info').showModal();};$('close-info').onclick=()=>$('info').close();$('info').onclick=e=>{if(e.target===$('info')){const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close();}};
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName)||$('info').open)return;if(['ArrowUp','ArrowDown',' ','w','s','W','S'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());if(e.key===' '&&!e.repeat)pause(!running);}});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{last=0;accumulator=0;});
let pointer=null;$('arena').style.touchAction='none';$('arena').onpointerdown=e=>{if(mode!=='human')return;$('arena').setPointerCapture(e.pointerId);pointer=(e.clientY-$('arena').getBoundingClientRect().top)/$('arena').getBoundingClientRect().height;};$('arena').onpointermove=e=>{if(pointer!==null)pointer=(e.clientY-$('arena').getBoundingClientRect().top)/$('arena').getBoundingClientRect().height;};$('arena').onpointerup=$('arena').onpointercancel=()=>pointer=null;
function control(){if(mode==='human')return pointer!==null?clamp((pointer-arena.paddle)*10,-1,1):(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);if(mode==='random')return random()*2-1;return (mode==='brain'?brain:shuffled).decide(blind?0:(arena.y-arena.paddle)*2);}
function step(){if(steps%4===0)action=control();arena.step(1/120,action,difficulty);steps++;if(steps%3===0){arena.trail.push([arena.x,arena.y]);if(arena.trail.length>18)arena.trail.shift();}if(arena.event==='hit'&&arena.rally%5===0)log(`连续接住 ${arena.rally} 球`);if(arena.event==='miss')log(`漏接 · 已自动重新发球`);if(steps%8===0){const b=mode==='shuffle'?shuffled:brain;let up=0,down=0;if(mode==='brain'||mode==='shuffle')for(let i=0;i<b.n;i++){up+=Math.abs(b.state[i])/b.n;down+=Math.abs(b.state[i+b.n])/b.n;}trace.push([up,down]);if(trace.length>160)trace.shift();}}
function stats(){const tries=arena.hits+arena.misses;$('accuracy').innerHTML=(tries?Math.round(arena.hits/tries*100):'—')+'<small>%</small>';$('attempts').textContent=tries?`${tries} 次接球机会`:'等待第一球';$('hits').textContent=arena.hits;$('best').textContent=arena.best;$('elapsed').textContent=time(arena.elapsed);$('rally').textContent=String(arena.rally).padStart(2,'0');$('arena-hint').textContent=mode==='human'?'↑ ↓ 控制球拍 · 支持触摸拖动':blind&&mode!=='random'?'感觉已切断 · 网络没有球位置信息':'感觉 → 回路活动 → 球拍动作';$('action-label').textContent=action>.08?'球拍向下 ↓':action<-.08?'球拍向上 ↑':'球拍保持 ·';const b=mode==='shuffle'?shuffled:brain;$('activity-value').textContent=b&&(mode==='brain'||mode==='shuffle')?(b.state.reduce((s,v)=>s+Math.abs(v),0)/b.state.length).toFixed(3):'—';}
function ctx(id){const c=$(id),r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d);}const g=c.getContext('2d');g.setTransform(d,0,0,d,0,0);g.clearRect(0,0,r.width,r.height);return [g,r.width,r.height];}
function drawArena(){const [g,w,h]=ctx('arena');g.fillStyle='#101817';g.fillRect(0,0,w,h);g.strokeStyle='#203026';g.lineWidth=.5;for(let x=20;x<w;x+=28){g.beginPath();g.moveTo(x,0);g.lineTo(x,h);g.stroke();}for(let y=20;y<h;y+=28){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}g.strokeStyle='#46543b';g.setLineDash([3,8]);g.beginPath();g.moveTo(w/2,95);g.lineTo(w/2,h-32);g.stroke();g.setLineDash([]);g.strokeStyle='#45583a';for(const [x,y,sx,sy] of [[13,13,1,1],[w-13,13,-1,1],[13,h-13,1,-1],[w-13,h-13,-1,-1]]){g.beginPath();g.moveTo(x+12*sx,y);g.lineTo(x,y);g.lineTo(x,y+12*sy);g.stroke();}
 for(let i=0;i<arena.trail.length;i++){const p=arena.trail[i];g.fillStyle=`rgba(193,245,129,${i/arena.trail.length*.25})`;g.beginPath();g.arc(p[0]*w,p[1]*h,2+i/arena.trail.length*2,0,Math.PI*2);g.fill();}
 g.shadowBlur=18;g.shadowColor='#b9f478';g.fillStyle='#b9f478';g.beginPath();g.roundRect(.035*w,arena.paddle*h-.09*h,7,.18*h,3);g.fill();g.shadowBlur=0;g.fillStyle='#c7d0bd';g.beginPath();g.roundRect(.965*w-7,arena.other*h-.09*h,7,.18*h,3);g.fill();g.shadowBlur=17;g.shadowColor='#d7fba7';g.fillStyle='#e3ffc2';g.beginPath();g.arc(arena.x*w,arena.y*h,5,0,Math.PI*2);g.fill();g.shadowBlur=0;
}
function drawNetwork(){const [g,w,h]=ctx('network');if(!brain)return;const b=mode==='shuffle'?shuffled:brain;const active=mode==='brain'||mode==='shuffle';const positions=b.names.map((name,i)=>{const group=i<8?0:i<20?1:i<35?2:i<43?3:4;const start=[0,8,20,35,43][group],count=[8,12,15,8,22][group];return [20+group*(w-40)/4,12+(i-start)/(count-1)*(h-26)];});for(let i=0;i<b.edges.length;i+=2){const e=b.edges[i],p=positions[e.from],q=positions[e.to];const intensity=active?Math.abs(b.state[e.from]):0;g.strokeStyle=`rgba(153,191,122,${.025+intensity*.18})`;g.lineWidth=.5;g.beginPath();g.moveTo(...p);g.lineTo(...q);g.stroke();}positions.forEach((p,i)=>{const v=active?Math.abs(b.state[i]):0;g.fillStyle=`rgba(185,244,120,${.2+Math.min(1,v*2)*.8})`;g.beginPath();g.arc(...p,1.4+v*3,0,Math.PI*2);g.fill();});}
function drawTrace(){const [g,w,h]=ctx('trace');g.strokeStyle='#2b362b';g.lineWidth=.5;for(let y=10;y<h;y+=20){g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke();}for(let k=0;k<2;k++){g.strokeStyle=k?'#7bb7c7':'#b9f478';g.lineWidth=1.6;g.beginPath();trace.forEach((p,i)=>{const x=i/159*w,y=h-9-clamp(p[k]*3,0,1)*(h-16);if(i===0)g.moveTo(x,y);else g.lineTo(x,y);});g.stroke();}}
let displayCounter=0;function frame(now){const dt=last?Math.min((now-last)/1000,.05):0;last=now;if(running&&!$('info').open){accumulator+=dt*speed;while(accumulator>=1/120){step();accumulator-=1/120;}}drawArena();drawNetwork();drawTrace();if(displayCounter++%6===0)stats();requestAnimationFrame(frame);}requestAnimationFrame(frame);
$('export').onclick=()=>{const b=new Blob([JSON.stringify({app:'Flylab Pong',model:'flyvis type-level rate reduction; engineered position-error input; supervised readout',dataset:'fib25-fib19_v2.2',seed:42,mode,difficulty,blind,elapsed:arena.elapsed,hits:arena.hits,misses:arena.misses,best:arena.best,comparison,log:logs},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='flylab-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('compare').onclick=async()=>{if(!ready)return;const button=$('compare');button.disabled=true;button.textContent='对照计算中…';const wasRunning=running;pause(false);const out=[];for(const kind of ['brain','shuffle','random']){await new Promise(r=>setTimeout(r,25));const testArena=new Arena(42),b=new Brain(dataset,kind==='shuffle');if(kind!=='random')b.calibrate();const r=rng(42);let a=0;for(let i=0;i<14400;i++){if(i%4===0)a=kind==='random'?r()*2-1:b.decide((testArena.y-testArena.paddle)*2);testArena.step(1/120,a,1);}out.push({mode:kind,hits:testArena.hits,misses:testArena.misses,rate:testArena.hits/(testArena.hits+testArena.misses)});}comparison=out;$('result-bars').replaceChildren(...out.map(o=>{const row=document.createElement('div');row.className='result-row';row.innerHTML=`<span>${names[o.mode]}</span><div class="bar"><i style="width:${o.rate*100}%"></i></div><strong>${Math.round(o.rate*100)}%</strong>`;return row;}));$('results').hidden=false;log('对照完成 · 结果见下方');button.disabled=false;button.innerHTML='重新运行对照 <span>↗</span>';pause(wasRunning);$('results').scrollIntoView({behavior:'smooth',block:'nearest'});};
let dataset;try{const response=await fetch('data/flyvis.json');if(!response.ok)throw new Error(`HTTP ${response.status}`);dataset=await response.json();brain=new Brain(dataset);shuffled=new Brain(dataset,true);await new Promise(r=>setTimeout(r,30));brain.calibrate();shuffled.calibrate();ready=true;$('toggle').disabled=false;log('65 类细胞已载入 · 输出接口已校准');pause(true);}catch(error){$('status').textContent='数据加载失败';$('toggle').textContent='请刷新重试';$('compare').disabled=true;log(`无法加载回路：${error.message}`);}
